class DTriFiguri {
    val M = 305
    val INF = 1_000_000_000
    val possibleKnight = arrayOf(
        Point.of(2, 1), Point.of(-2, 1), Point.of(2, -1), Point.of(-2, -1),
        Point.of(1, 2), Point.of(-1, 2), Point.of(1, -2), Point.of(-1, -2)
    )
    // dist will be initialized in solve or lateinit
    lateinit var dist: Array<Array<Point>>

    private fun inBounds(p: Point): Boolean = p.x in 0 until N && p.y in 0 until N

    fun solve(testNumber: Int, `in`: InputReader, out: PrintWriter) {
        N = `in`.nextInt()
        val pos = Array<Point>(N * N) { Point(0,0) }
        val A = Array(N) { IntArray(N) }
        for (x in 0 until N) {
            for (y in 0 until N) {
                A[x][y] = `in`.nextInt() - 1
                pos[A[x][y]] = Point.of(x, y)
            }
        }

        dist = Array(M) { Array(M) { Point.of(INF, INF) } }
        for (i in 0 until M) dist[i][i] = Point.of(0, 0)

        for (x in 0 until N) {
            for (y in 0 until N) {
                // Knight
                for (move in possibleKnight) {
                    val nx = x + move.x
                    val ny = y + move.y
                    if (inBounds(Point.of(nx, ny))) {
                        dist[Point.hash(x, y, 0)][Point.hash(nx, ny, 0)] = Point.of(1, 0)
                    }
                }
                // Bishop
                for (i in -N + 1 until N) { // -N+1 to N-1 inclusive
                    val nx = x + i
                    var ny = y + i
                    if (inBounds(Point.of(nx, ny))) {
                        dist[Point.hash(x, y, 1)][Point.hash(nx, ny, 1)] = Point.of(1, 0)
                    }
                    ny = y - i
                    if (inBounds(Point.of(nx, ny))) {
                        dist[Point.hash(x, y, 1)][Point.hash(nx, ny, 1)] = Point.of(1, 0)
                    }
                }
                // Rook
                for (i in 0 until N) {
                    var nx = i
                    var ny = y
                    dist[Point.hash(x, y, 2)][Point.hash(nx, ny, 2)] = Point.of(1, 0)
                    nx = x
                    ny = i
                    dist[Point.hash(x, y, 2)][Point.hash(nx, ny, 2)] = Point.of(1, 0)
                }
                // Piece changes
                for (i in 0..2) {
                    for (j in 0..2) {
                        if (i != j) {
                            dist[Point.hash(x, y, i)][Point.hash(x, y, j)] = Point.of(1, 1)
                        }
                    }
                }
            }
        }

        // Floyd-Warshall
        for (k in 0 until M) {
            for (i in 0 until M) {
                for (j in 0 until M) {
                    dist[i][j] = Point.min(dist[i][j], Point.sum(dist[i][k], dist[k][j]))
                }
            }
        }

        val dp = Array(N * N) { Array(3) { Point.of(INF, INF) } }
        for (j in 0..2) dp[0][j] = Point.of(0, 0)

        for (i in 0 until N * N - 1) {
            for (j in 0..2) {
                for (k in 0..2) {
                    val fromHash = Point.hash(pos[i].x, pos[i].y, j)
                    val toHash = Point.hash(pos[i+1].x, pos[i+1].y, k)
                    dp[i+1][k] = Point.min(dp[i+1][k], Point.sum(dp[i][j], dist[fromHash][toHash]))
                }
            }
        }

        var ans = Point.of(INF, INF)
        for (j in 0..2) ans = Point.min(ans, dp[N*N-1][j])

        out.print(ans.toString())
    }
}
